INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch11$PT156-S2-Q18$batch11$, 156, 2, 18, $batch11$Sufficient Assumption$batch11$, $batch11$Dapolito: The city council recently passed a rent-control ordinance. But a recent study of fifteen local communities shows clearly that rent control increases the price and lowers the quality and availability of rental units. Thus, it can be concluded that it is not the city council’s objective to preserve the quality and availability of local rentals.$batch11$, $batch11$Dapolito’s conclusion follows logically if which one of the following is assumed?$batch11$, $batch11$C$batch11$, true, $batch11$Batch 11; question text from local bank.$batch11$ FROM lr_sections s WHERE s.preptest=156 AND s.section=2 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT156-S2-Q18$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$A$batch11$, $batch11$The recent study of local rent-control ordinances was conducted by impartial investigators.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT156-S2-Q18$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$A$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$B$batch11$, $batch11$Rent control is not an appropriate topic for consideration by the city council.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT156-S2-Q18$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$B$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$C$batch11$, $batch11$The members of the city council who voted for rent control agree with the study’s conclusions about rent control.$batch11$, $batch11$Correct$batch11$, true FROM lr_questions q WHERE q.qid=$batch11$PT156-S2-Q18$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$C$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$D$batch11$, $batch11$Some members of the city council who voted for rent control stand to profit from rent control.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT156-S2-Q18$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$D$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$E$batch11$, $batch11$The city council sometimes acts in an arbitrary and irrational manner.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT156-S2-Q18$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$E$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT156-S2-Q18$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Conclusion$batch11$, $batch11$The city council's objective is not to preserve the quality and availability of local rentals.$batch11$), (1, $batch11$Evidence$batch11$, $batch11$The council passed rent control. A study shows rent control lowers quality and availability.$batch11$), (2, $batch11$Evaluate$batch11$, $batch11$A study showing rent control hurts rentals doesn't tell us what the council wanted. Maybe it never saw the study or disagreed with it. If the council members who voted for rent control agreed it hurts rentals, then voting for it means they didn't aim to preserve them.$batch11$), (3, $batch11$Goal$batch11$, $batch11$The council members who voted for rent control agree with the study.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT156-S2-Q18$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch11$A$batch11$, $batch11$An impartial study makes the facts stronger, but says nothing about what the council believed or intended.$batch11$), ($batch11$B$batch11$, $batch11$Whether the council should consider rent control doesn't reveal its objective.$batch11$), ($batch11$C$batch11$, $batch11$If they knew rent control hurts rentals and passed it anyway, preserving rentals wasn't their goal.$batch11$), ($batch11$D$batch11$, $batch11$Some members profiting doesn't show the council as a whole didn't care about rentals.$batch11$), ($batch11$E$batch11$, $batch11$Acting arbitrarily sometimes doesn't tell us what the objective was here.$batch11$)) v(letter,body) WHERE q.qid=$batch11$PT156-S2-Q18$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
